نقش سازمانی: مدیر تعمیرات و قابلیت اطمینان (maintenance_manager)

درخواست کاربر:
دسترسی 85% است و هدف 92%. چطور به هدف برسیم؟ (مدیر تعمیرات — معدن روی مهدی‌آباد)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "maintenance_work_orders",
      "description": "دستورات کار تعمیراتی",
      "dimensions": [
        "equipment",
        "type",
        "period"
      ],
      "measures": [
        "planned",
        "completed",
        "overdue"
      ]
    },
    {
      "dataset": "equipment_downtime",
      "description": "توقف تجهیزات به تفکیک نوع و علت",
      "dimensions": [
        "equipment",
        "reason",
        "period"
      ],
      "measures": [
        "hours",
        "cost"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "availability",
      "description": "نرخ دسترسی تجهیز",
      "formula": "زمان کار / (زمان کار + زمان توقف)",
      "unit": "درصد",
      "dimensions": [
        "equipment"
      ]
    }
  ],
  "business_context": [
    "ناوگان تجهیزات معدنی شامل شاول، دامپر، سنگ‌شکن و آسیاب",
    "تعمیرات پیشگیرانه و اضطراری با بودجهٔ سالانه",
    "قطعات حیاتی با زمان تحویل طولانی (۳ تا ۶ ماه)"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "availability"
    ],
    "period": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "current": 85,
  "target": 92
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "maintenance_work_orders",
    "filters": {
      "period": "last_3_months"
    }
  }
}

TOOL_OBSERVATION:
{
  "breakdown_cost_m": 769,
  "pm_cost_m": 229
}

